<script lang="ts">
  import { onMount } from 'svelte';
  import { getAuthUser } from '$features/auth/ui/stores/auth.store.svelte';
  import type { UserRole } from '$features/auth/domain/entities';
  import { getUsersState, loadUsers, toggleUserActive, updateUser } from '../stores/users.store.svelte';
  const state = getUsersState(); const currentUser = $derived(getAuthUser());
  const roleLabels: Record<UserRole, string> = { admin: 'Administrador', support: 'Soporte', sales: 'Ventas' };
  let search = $state(''); let roleFilter = $state('all'); let statusFilter = $state('all'); let editing = $state<ReturnType<typeof getAuthUser>>(); let editingId = $state(''); let fullName = $state(''); let phone = $state(''); let role = $state<UserRole>('support'); let isActive = $state(true); let showForm = $state(false);
  const filteredUsers = $derived(state.users.filter((user) => { const term = search.trim().toLowerCase(); const matchesSearch = !term || [user.fullName, user.email, user.phone ?? ''].some((value) => value.toLowerCase().includes(term)); return matchesSearch && (roleFilter === 'all' || user.role === roleFilter) && (statusFilter === 'all' || (statusFilter === 'active' ? user.isActive : !user.isActive)); }));
  const activeCount = $derived(state.users.filter((user) => user.isActive).length);
  const adminCount = $derived(state.users.filter((user) => user.role === 'admin' && user.isActive).length);
  onMount(loadUsers);
  function openEdit(user: typeof state.users[number]) { editingId = user.id; editing = getAuthUser(); fullName = user.fullName; phone = user.phone ?? ''; role = user.role; isActive = user.isActive; showForm = true; }
  function closeForm() { if (!state.saving) showForm = false; }
  async function save(event: SubmitEvent) { event.preventDefault(); const user = state.users.find((item) => item.id === editingId); if (!user || state.saving) return; if (user.id === currentUser?.id && (!isActive || role !== 'admin')) { state.error = 'No puedes desactivar tu propia cuenta ni quitarte el rol de administrador.'; return; } await updateUser(user.id, { fullName: fullName.trim(), phone: phone.trim() || null, role, isActive }); if (!state.error) showForm = false; }
  async function toggle(user: typeof state.users[number]) { if (user.id === currentUser?.id) { return; } if (!confirm(`¿Confirmas ${user.isActive ? 'desactivar' : 'activar'} a ${user.fullName}?`)) return; await toggleUserActive(user); }
  function date(value: string) { return new Intl.DateTimeFormat('es', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(value)); }
</script>
<svelte:head><title>Usuarios | SOLUX Backoffice</title></svelte:head>
<section class="page"><div class="section-head"><div><div class="eyebrow">Administración</div><h2>Gestión de usuarios</h2></div><p>Administra cuentas internas, roles y acceso al backoffice.</p></div>
  <div class="stats"><article><span>Usuarios registrados</span><strong>{state.users.length}</strong></article><article><span>Cuentas activas</span><strong>{activeCount}</strong></article><article><span>Administradores</span><strong>{adminCount}</strong></article></div>
  <div class="toolbar"><div class="search"><label>Buscar</label><input bind:value={search} placeholder="Nombre, correo o teléfono" /></div><div><label>Rol</label><select bind:value={roleFilter}><option value="all">Todos los roles</option><option value="admin">Administrador</option><option value="support">Soporte</option><option value="sales">Ventas</option></select></div><div><label>Estado</label><select bind:value={statusFilter}><option value="all">Todos</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select></div><button type="button" onclick={() => (state.error = 'La creación de cuentas requiere Edge Function segura de Supabase Auth.')} disabled={state.saving}>Nuevo usuario</button></div>
  {#if state.error}<p class="notice error" role="alert">{state.error}</p>{/if}{#if state.success}<p class="notice success" role="status">{state.success}</p>{/if}
  {#if showForm}<form class="card editor" onsubmit={save}><div class="editor-head"><div><h3>Editar usuario</h3><p>Actualiza perfil, rol y acceso.</p></div><button type="button" onclick={closeForm} disabled={state.saving}>Cancelar</button></div><div class="form-grid"><div><label>Nombre completo</label><input bind:value={fullName} required maxlength="120" /></div><div><label>Correo</label><input value={state.users.find((u) => u.id === editingId)?.email ?? ''} disabled /></div><div><label>Teléfono</label><input bind:value={phone} maxlength="40" /></div><div><label>Rol</label><select bind:value={role}><option value="admin">Administrador</option><option value="support">Soporte</option><option value="sales">Ventas</option></select></div><label class="active-toggle"><input type="checkbox" bind:checked={isActive} /> Cuenta activa</label></div><div class="editor-actions"><button type="submit" disabled={state.saving}>{state.saving ? 'Guardando…' : 'Guardar cambios'}</button></div></form>{/if}
  <div class="card table-card">{#if state.loading}<p class="empty">Cargando usuarios…</p>{:else if filteredUsers.length === 0}<p class="empty">No hay usuarios que coincidan con los filtros.</p>{:else}<div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Alta</th><th>Acciones</th></tr></thead><tbody>{#each filteredUsers as user (user.id)}<tr><td><div class="identity"><span class="avatar">{user.fullName.trim().charAt(0).toUpperCase() || '?'}</span><div><strong>{user.fullName}</strong><small>{user.email}</small>{#if user.phone}<small>{user.phone}</small>{/if}</div></div></td><td><span class="role">{roleLabels[user.role]}</span></td><td><span class="status">{user.isActive ? 'Activo' : 'Inactivo'}</span></td><td>{date(user.createdAt)}</td><td><div class="actions"><button type="button" onclick={() => openEdit(user)} disabled={state.saving || state.updatingUsers.includes(user.id)}>Editar</button><button type="button" disabled={user.id === currentUser?.id || state.saving || state.updatingUsers.includes(user.id)} onclick={() => toggle(user)}>{user.isActive ? 'Desactivar' : 'Activar'}</button></div></td></tr>{/each}</tbody></table></div>{/if}<div class="table-footer">Mostrando {filteredUsers.length} de {state.users.length} usuarios</div></div>
</section>
<style>.page{padding:clamp(20px,3vw,36px);max-width:1400px;margin:0 auto}.section-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:24px}.section-head h2{margin:4px 0}.section-head p{color:var(--color-muted);max-width:380px}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--color-primary)}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:20px}.stats article,.card{background:var(--color-surface);border:1px solid var(--color-border);border-radius:16px}.stats article{padding:18px;display:grid;gap:8px}.stats span{font-size:13px;color:var(--color-muted)}.stats strong{font-size:28px}.toolbar{display:flex;align-items:end;gap:12px;padding:16px;background:var(--color-surface);border:1px solid var(--color-border);border-radius:16px;margin-bottom:16px}.toolbar>div{display:grid;gap:6px;min-width:150px}.toolbar .search{flex:1}.toolbar input,.toolbar select,input{width:100%;box-sizing:border-box;min-height:42px;padding:9px 11px;border:1px solid var(--color-border);border-radius:10px;background:var(--color-background);color:var(--color-text)}button{border:1px solid var(--color-border);border-radius:9px;background:transparent;color:var(--color-text);padding:9px 11px;font-weight:600;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}.table-card{overflow:hidden}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;text-align:left;font-size:13px}th{padding:13px 16px;background:var(--color-surface-2);font-size:11px;color:var(--color-muted)}td{padding:14px 16px;border-top:1px solid var(--color-border)}.identity{display:flex;align-items:center;gap:11px}.identity>div{display:grid;gap:3px}.identity small{font-size:12px;color:var(--color-muted)}.avatar{width:38px;height:38px;display:grid;place-items:center;border-radius:12px;background:var(--color-surface-2);color:var(--color-primary);font-weight:800}.role,.status{display:inline-flex;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:700;background:var(--color-surface-2)}.actions{display:flex;gap:6px}.table-footer{padding:12px 16px;border-top:1px solid var(--color-border);font-size:12px;color:var(--color-muted)}.empty{padding:30px;text-align:center;color:var(--color-muted)}.notice{padding:12px 14px;border-radius:10px;font-size:13px;margin:12px 0}.notice.error{color:#b91c1c;background:#fee2e2}.notice.success{color:#15803d;background:#dcfce7}.editor{padding:20px;margin-bottom:16px}.editor-head{display:flex;justify-content:space-between;gap:16px;margin-bottom:18px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.form-grid>div{display:grid;gap:6px}.active-toggle{display:flex;align-items:center;gap:8px}.editor-actions{display:flex;justify-content:flex-end;margin-top:18px}@media(max-width:850px){.section-head{display:block}.toolbar{flex-wrap:wrap}.toolbar .search{flex-basis:100%}.stats{gap:8px}}@media(max-width:520px){.stats,.form-grid{grid-template-columns:1fr}}
</style>
